import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int total = sc.nextInt();
        int target = sc.nextInt();
        double[] probabilities = new double[total];
        for (int i = 0; i < total; i++) {
            probabilities[i] = sc.nextDouble();
        }

        int positiveCount = 0;
        for (double p : probabilities) {
            if (p > 1e-6) positiveCount++;
        }

        if (positiveCount <= target) {
            for (double p : probabilities) {
                System.out.print((p > 1e-6 ? "1 " : "0 "));
            }
            System.out.println();
            return;
        }

        double[] result = new double[total];
        double[] dynamicProg = new double[1 << total];
        Arrays.fill(dynamicProg, 0.0);
        dynamicProg[0] = 1.0;

        for (int mask = 0; mask < (1 << total); mask++) {
            double sumProbs = 0.0;
            for (int i = 0; i < total; i++) {
                if ((mask & (1 << i)) != 0) {
                    sumProbs += probabilities[i];
                }
            }
            if (sumProbs >= 0.99999) continue;
            for (int i = 0; i < total; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int nextMask = mask | (1 << i);
                dynamicProg[nextMask] += dynamicProg[mask] * probabilities[i] / (1 - sumProbs);
            }
        }

        for (int mask = 0; mask < (1 << total); mask++) {
            int countBits = 0;
            for (int i = 0; i < total; i++) {
                if ((mask & (1 << i)) != 0) countBits++;
            }
            if (countBits != target) continue;
            for (int i = 0; i < total; i++) {
                if ((mask & (1 << i)) != 0) {
                    result[i] += dynamicProg[mask];
                }
            }
        }

        System.out.printf(Locale.US, "%.13f", 0.0);
        for (double v : result) {
            System.out.printf(Locale.US, "%.13f ", v);
        }
        System.out.println();
    }
}
